<div class="mb-6"><p class="text-sm font-medium text-blue-600">Asistencia</p><h1 class="text-2xl font-bold">Horarios y sesiones</h1><p class="mt-1 text-sm text-slate-500">Asigne una jornada a cada persona o sesiones específicas a docentes por curso.</p></div>
<section class="grid gap-5 lg:grid-cols-3">
<article class="rounded-2xl border bg-white p-5 shadow-sm"><h2 class="font-semibold">Asignar jornada</h2><form method="post" action="index.php?url=horarios_guardar" class="mt-4 space-y-3"><?= campoCsrf() ?><input type="hidden" name="entidad" value="jornada_persona"><label class="form-label">Persona<select required name="id_persona" class="form-input"><option value="">Seleccione</option><?php foreach($personas as $p): ?><option value="<?= $p['id_persona'] ?>"><?= htmlspecialchars($p['nombre'].' · '.$p['perfiles']) ?></option><?php endforeach; ?></select></label><label class="form-label">Jornada<select required name="id_jornada" class="form-input"><option value="">Seleccione</option><?php foreach($jornadas as $j): ?><option value="<?= $j['id_jornada'] ?>"><?= htmlspecialchars($j['nombre'].' · '.$j['hora_entrada'].'-'.$j['hora_salida']) ?></option><?php endforeach; ?></select></label><label class="form-label">Desde<input required type="date" name="fecha_inicio" value="<?= date('Y-m-d') ?>" class="form-input"></label><label class="form-label">Hasta <span class="font-normal text-slate-400">(opcional)</span><input type="date" name="fecha_fin" class="form-input"></label><button class="w-full rounded-xl bg-blue-600 py-2 text-sm font-semibold text-white">Asignar jornada</button></form></article>
<article class="rounded-2xl border bg-white p-5 shadow-sm"><h2 class="font-semibold">Nueva asignatura</h2><form method="post" action="index.php?url=horarios_guardar" class="mt-4 flex gap-2"><?= campoCsrf() ?><input type="hidden" name="entidad" value="asignatura"><input required name="nombre" class="form-input mt-0" placeholder="Matemática"><button class="rounded-xl bg-blue-600 px-3 text-sm font-semibold text-white">Agregar</button></form><div class="mt-4 space-y-2"><?php foreach($asignaturas as $a): ?><div class="rounded-xl bg-slate-50 p-2 text-sm"><?= htmlspecialchars($a['nombre']) ?></div><?php endforeach; ?></div></article>
<article class="rounded-2xl border bg-white p-5 shadow-sm"><h2 class="font-semibold">Sesión docente por curso</h2><form method="post" action="index.php?url=horarios_guardar" class="mt-4 grid gap-3"><?= campoCsrf() ?><input type="hidden" name="entidad" value="sesion"><select required name="id_vinculo" class="form-input mt-0"><option value="">Docente</option><?php foreach($docentes as $d): ?><option value="<?= $d['id_vinculo'] ?>"><?= htmlspecialchars($d['nombre']) ?></option><?php endforeach; ?></select><select required name="id_periodo_academico" class="form-input mt-0"><option value="">Período</option><?php foreach($periodos as $p): ?><option value="<?= $p['id_periodo_academico'] ?>"><?= htmlspecialchars($p['nombre']) ?></option><?php endforeach; ?></select><select required name="id_seccion" class="form-input mt-0"><option value="">Sección</option><?php foreach($secciones as $s): ?><option value="<?= $s['id_seccion'] ?>"><?= htmlspecialchars($s['nombre']) ?></option><?php endforeach; ?></select><select required name="id_asignatura" class="form-input mt-0"><option value="">Asignatura</option><?php foreach($asignaturas as $a): ?><option value="<?= $a['id_asignatura'] ?>"><?= htmlspecialchars($a['nombre']) ?></option><?php endforeach; ?></select><select required name="dia_semana" class="form-input mt-0"><option value="1">Lunes</option><option value="2">Martes</option><option value="3">Miércoles</option><option value="4">Jueves</option><option value="5">Viernes</option><option value="6">Sábado</option></select><div class="grid grid-cols-3 gap-2"><input required type="time" name="hora_inicio" class="form-input mt-0"><input required type="time" name="hora_fin" class="form-input mt-0"><input required type="number" min="0" name="tolerancia_minutos" value="10" class="form-input mt-0"></div><button class="rounded-xl bg-violet-600 py-2 text-sm font-semibold text-white">Programar sesión</button></form></article>
</section>
<section class="mt-6 grid gap-5 lg:grid-cols-2"><article class="rounded-2xl border bg-white p-5 shadow-sm"><h2 class="font-semibold">Jornadas asignadas</h2><div class="mt-3 space-y-2"><?php foreach($asignaciones as $a): ?><div class="rounded-xl bg-slate-50 p-3 text-sm"><strong><?= htmlspecialchars($a['persona']) ?></strong><span class="block text-slate-500"><?= htmlspecialchars($a['jornada'].' · desde '.$a['fecha_inicio']) ?></span></div><?php endforeach; ?></div></article><article class="rounded-2xl border bg-white p-5 shadow-sm"><h2 class="font-semibold">Sesiones programadas</h2><div class="mt-3 space-y-2"><?php foreach($cargas as $c): ?><div class="rounded-xl bg-slate-50 p-3 text-sm"><strong><?= htmlspecialchars($c['docente'].' · '.$c['asignatura']) ?></strong><span class="block text-slate-500"><?= htmlspecialchars(['','Lun','Mar','Mié','Jue','Vie','Sáb','Dom'][$c['dia_semana']].' · '.$c['hora_inicio'].'-'.$c['hora_fin'].' · '.$c['seccion']) ?></span></div><?php endforeach; ?></div></article></section>
